// === Tab: mySketch ===
const sketch = (p) => {
    let H = 1024;
    let W = 1024;

    let min_width;
    let max_width;

    let G;

    let SEED;

    let PL = [];

    p.setup = () => {
        p.createCanvas(p.windowWidth, p.windowHeight);
        G = p.createGraphics(W, H);

        min_width = p.min(p.width, p.height);
        max_width = p.max(p.width, p.height);

        SEED = p.random()*998244353;

        p.randomSeed(SEED);
        p.noiseSeed(SEED);


        BACK_COL = 10;

        G.background(BACK_COL);
        G.colorMode(p.HSB);

        let N = 4;
        for(let i=0;i<N;++i){
            for(let j=0;j<N;++j){
                PL.push(new Plot(
                    .5*W/N+W/N*i,
                    .5*H/N+H/N*j,
                    W/N,
                    H/N,
                    )
                );
            }
        }
        for(let i=0;i<PL.length;++i){
            PL[i].draw();
        }
    };

    p.draw = () => {
        p.blendMode(p.BLEND);
        p.background(BACK_COL);

        p.image(G, (p.width-min_width)/2, (p.height-min_width)/2, min_width, min_width, 0, 0, W, H);
    };

    class Plot{
        center;
        width;
        height;
        a;
        b;
        t1;
        t2;
        init_x;
        a_step;
        constructor(x,y,w,h){
            this.center = p.createVector(x,y);
            this.width = w;
            this.height = h;

            this.init_x = p.random(-.6,.6);
            this.a = p.random(1, 10);
            this.b = p.random(-.7,-.1);
            this.t1 = p.random(.005,.1);
            this.t2 = p.int(p.random(0,360));

            this.a_step = p.random(-.07,.07);
        }

        draw(){
            let x = this.init_x;
            let angle = 0;
            let pos1, pos2;

            let lx = this.center.x - this.width/2;
            let ly = this.center.y - this.height/2;
            let rx = this.center.x + this.width/2;
            let ry = this.center.y + this.height/2;

            pos1 = p.createVector(x, x);
            for(let i=0;i<5000;++i){
                if(i%2==0){
                    pos2 = p.createVector(pos1.y, this.f(pos1.x));
                }
                else{
                    pos2 = p.createVector(pos1.y, pos1.y);
                }

                let rp1 = p5.Vector.rotate(pos1, angle);
                angle += p.random(1)<.002?this.a_step:0;
                let rp2 = p5.Vector.rotate(pos2, angle);

                G.strokeWeight(2);
                G.stroke(p.int(i*this.t1+this.t2)%360,75,100);

                let x1 = p.map(rp1.x, -1.,1., lx, rx);
                let y1 = p.map(rp1.y, -.9,1.1, ly, ry);
                let x2 = p.map(rp2.x, -1.,1., lx, rx);
                let y2 = p.map(rp2.y, -.9,1.1, ly, ry);
                G.line(x1, y1, x2, y2);

                pos1 = pos2;
            }
        }

        f(x) {
            return p.exp(-this.a*x*x) + this.b;
        }
    }


};

new p5(sketch);

